INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '삼성전자 연봉협상 어떻게 하셨나요?', '올해 연봉협상 시즌인데 작년 대비 몇 % 올리셨는지 궁금합니다. 저는 5% 요청했다가 3%로 조정됐어요. 대기업도 요즘 인상폭이 줄었나요?', '대기업·중견기업', 24, NOW() - INTERVAL '1 day'),
(NULL, '현대차 인턴 후기 솔직하게', '6개월 인턴 끝났습니다. 정규직 전환 기준이 생각보다 까다로웠고, 업무량은 정규직이랑 별 차이 없었어요. 그래도 대기업 경험 자체는 도움됐습니다.', '대기업·중견기업', 37, NOW() - INTERVAL '2 days'),
(NULL, 'LG전자 복지 솔직 후기', '타회사 다니다 이직했는데 복지는 확실히 좋습니다. 사내 카페, 헬스장, 어린이집까지. 그런데 눈치문화가 생각보다 심해요.', '대기업·중견기업', 18, NOW() - INTERVAL '3 days'),
(NULL, '대기업 팀장이 되고 싶다는 생각이 사라졌습니다', '주임->대리->과장 되면서 점점 윗사람 리스크를 떠안는 구조를 봤어요. 팀장은 실적도 책임지고 HR도 하고... 연봉 차이가 크지 않으면 굳이 올라갈 이유가 없는 것 같아요.', '대기업·중견기업', 89, NOW() - INTERVAL '4 days'),
(NULL, 'SK하이닉스 요즘 야근 어때요?', 'HBM 호황이라는데 현장 분위기 어떤지 궁금합니다. 야근이 많이 늘었나요?', '대기업·중견기업', 41, NOW() - INTERVAL '5 days'),
(NULL, '대기업 10년차 솔직한 소감', '입사할 때 꿈과 지금 현실이 많이 다릅니다. 안정성은 최고인데 성장한다는 느낌이 없어요. 40대에 어쩌나 고민 중입니다.', '대기업·중견기업', 112, NOW() - INTERVAL '6 days'),
(NULL, '카카오 최근 분위기 어때요?', '작년에 많이 안 좋다는 얘기 들었는데 지금도 그런가요? 이직 고려 중인데 내부 분위기 궁금합니다.', '대기업·중견기업', 55, NOW() - INTERVAL '7 days'),
(NULL, '대기업 입사 3개월차 솔직 후기', '대학교 때 그렇게 원하던 대기업에 왔는데... 생각보다 저는 소심한 사람이었나봐요. 회의실에서 의견 말하기가 너무 무서워요.', '대기업·중견기업', 76, NOW() - INTERVAL '8 days'),
(NULL, '네이버 vs 카카오 처우 비교', '두 곳 모두 오퍼 받은 상황입니다. 기본급은 비슷한데 인센티브 구조가 달라서 고민이에요. 각 회사 다니시는 분 의견 부탁드립니다.', '대기업·중견기업', 94, NOW() - INTERVAL '9 days'),
(NULL, '중견기업 대기업 이직 성공기', '5년간 중견기업 다니다 대기업 이직 성공했습니다. 준비 기간 1년, 서류만 30군데 넣었어요. 포기하지 마세요.', '대기업·중견기업', 128, NOW() - INTERVAL '10 days'),
(NULL, '포스코 생산직 vs 사무직 처우 차이', '실제로 연봉은 생산직이 더 높다는데 맞나요? 복지나 워라밸은 어떤가요?', '대기업·중견기업', 33, NOW() - INTERVAL '11 days'),
(NULL, '삼성 그룹사 간 이동 어렵나요?', '삼성전자에서 삼성SDS로 내부 이동 가능한지 궁금합니다. 아니면 퇴직 후 재입사해야 하나요?', '대기업·중견기업', 27, NOW() - INTERVAL '12 days'),
(NULL, '대기업 꼰대 문화 여전한가요?', '2025년인데도 "라떼는~" 하는 분들 계신가요? 회사 선택할 때 가장 걱정되는 부분입니다.', '대기업·중견기업', 67, NOW() - INTERVAL '13 days'),
(NULL, 'KT 통신 3사 중 어디가 나은가요?', 'SKT, KT, LGU+ 각 회사 분위기 다들 어때요? 공채 준비 중인데 업계 분위기 궁금합니다.', '대기업·중견기업', 44, NOW() - INTERVAL '14 days'),
(NULL, '대기업 육아휴직 눈치 실제로 어때요?', '법적으로 보장되는 건 알겠는데 실제로 쓰면 어떻게 되는지 솔직하게 알고 싶습니다.', '대기업·중견기업', 83, NOW() - INTERVAL '15 days'),
(NULL, '롯데 계열사 요즘 어떤가요?', '예전엔 보수적이라는 인식이 강했는데 요즘도 그런가요? 지인이 롯데케미칼 추천해줘서 고민 중입니다.', '대기업·중견기업', 21, NOW() - INTERVAL '16 days'),
(NULL, '대기업 과장 달고 나서 변한 것들', '드디어 과장이 됐는데 솔직히 책임만 늘고 자유는 없어졌습니다. 팀원들 눈치도 봐야 하고... 대리 때가 그립네요.', '대기업·중견기업', 98, NOW() - INTERVAL '17 days'),
(NULL, '현대모비스 이직 고려 중입니다', '지금 협력사 다니는데 현대모비스 공채 합격했어요. 처우 많이 다른가요?', '대기업·중견기업', 39, NOW() - INTERVAL '18 days'),
(NULL, 'GS칼텍스 vs 에쓰오일 비교', '정유사 두 곳 모두 최종까지 갔습니다. 연봉은 비슷한데 복지랑 문화가 다르다는 얘기를 들었어요.', '대기업·중견기업', 52, NOW() - INTERVAL '19 days'),
(NULL, '대기업 연차 소진 눈치 없이 쓰는 법', '공식적으로는 눈치 주지 말라는데 실제론... 다들 어떻게 연차 쓰세요?', '대기업·중견기업', 71, NOW() - INTERVAL '20 days'),
(NULL, '삼성SDI 배터리 사업 요즘 분위기', '전기차 수요 둔화로 배터리 업황이 안 좋다고 하던데 내부 분위기 실제로 어때요?', '대기업·중견기업', 46, NOW() - INTERVAL '21 days'),
(NULL, '대기업 인사팀 솔직 후기', 'HR 부서 3년 있었는데 생각보다 훨씬 많은 정보를 알게 됩니다. 개인정보 다루는 게 부담스럽기도 해요.', '대기업·중견기업', 34, NOW() - INTERVAL '22 days'),
(NULL, '두산 계열사 이직하려는데', '두산에너빌리티 원자력 사업 커진다는데 지금 입사하면 성장 가능성 있을까요?', '대기업·중견기업', 28, NOW() - INTERVAL '23 days'),
(NULL, 'CJ그룹 문화 어때요?', '외식, 미디어, 물류 다 있는 그룹인데 각 계열사마다 문화가 많이 다를 것 같아요.', '대기업·중견기업', 19, NOW() - INTERVAL '24 days'),
(NULL, '대기업 사내 정치 어디까지 경험하셨나요?', '제가 너무 순진했나봐요. 성과보다 라인이 더 중요하다는 걸 3년 지나서야 알았습니다.', '대기업·중견기업', 104, NOW() - INTERVAL '25 days'),
(NULL, 'LS그룹 vs 효성그룹 비교', '중견 대기업급 두 곳 오퍼 비교 중입니다. 비슷한 처우인데 안정성이나 성장 가능성이 궁금해요.', '대기업·중견기업', 23, NOW() - INTERVAL '26 days'),
(NULL, '대기업 비정규직에서 정규직 전환 성공했습니다', '2년 기다렸어요. 전환 기준이 불투명해서 힘들었지만 결국 됐습니다. 포기하지 마세요.', '대기업·중견기업', 137, NOW() - INTERVAL '27 days'),
(NULL, '현대건설 요즘 현장 힘든가요?', '건설업 경기가 안 좋다는데 현대건설 내부 분위기 어때요? 야근이나 구조조정 걱정이 있나요?', '대기업·중견기업', 38, NOW() - INTERVAL '28 days'),
(NULL, '대기업 재직 중 MBA 가능한가요?', '야간/주말 MBA 생각 중인데 팀장한테 말하기가 좀 그래서요. 실제로 다니시는 분 계신가요?', '대기업·중견기업', 57, NOW() - INTERVAL '29 days'),
(NULL, '코웨이 같은 중견기업 솔직 후기', '대기업 선호하지만 사실 중견기업도 복지 좋은 곳 많잖아요. 오히려 의사결정 빠르고 좋을 수도 있다고 생각해요.', '대기업·중견기업', 42, NOW() - INTERVAL '30 days'),
(NULL, '대기업 신입 첫 월급 실수령액', '연봉 4000에 세금 떼고 실수령이 얼마나 되는지 궁금했는데 약 290만원 정도였어요. 생각보다 적네요.', '대기업·중견기업', 91, NOW() - INTERVAL '31 days'),
(NULL, '한화그룹 방산 쪽 어때요?', '방위산업이 성장한다는데 한화에어로스페이스 같은 곳은 실제 분위기 어떤가요?', '대기업·중견기업', 49, NOW() - INTERVAL '32 days'),
(NULL, '대기업 다니면서 부업 하시는 분?', '회사 규정상 겸업 금지인 곳이 많은데 실제로 투잡 하시는 분들 어떻게 하시나요?', '대기업·중견기업', 76, NOW() - INTERVAL '33 days'),
(NULL, '오리온, 농심 등 식품 대기업 어때요?', '식품 회사는 워라밸 좋다는 얘기도 있고 영업직은 힘들다는 얘기도 있어서 헷갈려요.', '대기업·중견기업', 31, NOW() - INTERVAL '34 days'),
(NULL, '대기업 퇴직금 어떻게 관리하세요?', 'IRP, 퇴직연금... 옵션이 많아서 헷갈립니다. 어떻게 관리하시는지 궁금해요.', '대기업·중견기업', 54, NOW() - INTERVAL '35 days'),
(NULL, 'KIA 오토랜드 생산직 현실', '현대차 생산직이 연봉 높다는 얘기 많은데 실제로 몸은 얼마나 힘든가요?', '대기업·중견기업', 63, NOW() - INTERVAL '36 days'),
(NULL, '대기업 임원 되는 비율이 얼마나 될까요?', '5000명 중에 몇 명이나 임원이 되는지 궁금합니다. 내부에서 보기엔 어때요?', '대기업·중견기업', 87, NOW() - INTERVAL '37 days'),
(NULL, '삼성물산 건설 vs 현대건설', '둘 다 최종면접 통보 받았습니다. 처우는 비슷한데 문화적으로 어떤 차이가 있나요?', '대기업·중견기업', 44, NOW() - INTERVAL '38 days'),
(NULL, '대기업 연구소 vs 사업부 선택', '신입 배치 때 연구소와 사업부 중 고민 중입니다. 장기적으로 어느 쪽이 유리할까요?', '대기업·중견기업', 66, NOW() - INTERVAL '39 days'),
(NULL, 'LG CNS 최근 어때요?', 'IT 서비스 회사 중에서 LG CNS 분위기 궁금합니다. 삼성SDS랑 비교하면 어떤가요?', '대기업·중견기업', 38, NOW() - INTERVAL '40 days'),
(NULL, '대기업 노조 실제로 도움이 되나요?', '노조 있는 회사 다니는데 솔직히 젊은 직원들한테는 별 도움이 안 되는 것 같아요. 의견 궁금합니다.', '대기업·중견기업', 72, NOW() - INTERVAL '41 days'),
(NULL, '신세계, 롯데 유통 계열 비교', '유통 대기업 두 곳 공채 결과 기다리는 중입니다. 어느 쪽이 나은지 의견 부탁드려요.', '대기업·중견기업', 26, NOW() - INTERVAL '42 days'),
(NULL, '대기업 파견직 솔직 후기', '대기업 건물 안에서 일하지만 정규직이 아니에요. 차별이 있긴 한데 배울 점도 많아요.', '대기업·중견기업', 59, NOW() - INTERVAL '43 days'),
(NULL, '현대중공업 조선소 사무직 현실', '조선소 사무직은 현장과 가깝다 보니 힘든 점도 있지만 업황이 좋아서 성과급이 좋다고 하더라고요.', '대기업·중견기업', 45, NOW() - INTERVAL '44 days'),
(NULL, '대기업 경력직 채용 과정 후기', '서류->인적성->임원면접 3단계였습니다. 경력직인데 인적성 보는 곳이 많더라고요.', '대기업·중견기업', 83, NOW() - INTERVAL '45 days'),
(NULL, 'SK텔레콤 요즘 분위기 어떤가요', '보안사고 이후로 분위기가 많이 바뀌었을 것 같아서요. 내부 직원 분들 솔직한 후기 부탁드립니다.', '대기업·중견기업', 97, NOW() - INTERVAL '46 days'),
(NULL, '대기업 해외 발령 가면 좋은건가요?', '해외 주재원 발령 기회가 생겼는데 가족이 있어서 고민입니다. 다녀오신 분 솔직하게 어때요?', '대기업·중견기업', 61, NOW() - INTERVAL '47 days'),
(NULL, '한국타이어 vs 금호타이어 비교', '타이어 업계 두 회사 오퍼 비교 중입니다. 업계 분위기 아시는 분 계신가요?', '대기업·중견기업', 18, NOW() - INTERVAL '48 days'),
(NULL, '대기업 40대 퇴직 후 뭐 하시나요?', '선배들 보면 40대 중반에 퇴직하는 분이 많던데 이후 커리어 어떻게 되는지 궁금합니다.', '대기업·중견기업', 103, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '중소기업 5년 다니고 느낀 점', '연봉은 대기업보다 적지만 여기서 배운 것들이 많아요. 대기업보다 넓게 일할 수 있었습니다. 이직할 때 경력 인정받기가 어렵다는 게 단점이에요.', '중소기업', 54, NOW() - INTERVAL '1 day'),
(NULL, '중소기업 연봉 협상 팁 공유', '중소기업에서는 대기업처럼 밴드가 정해져 있지 않아서 협상이 더 유연합니다. 처음부터 높게 제시하는 게 낫더라고요.', '중소기업', 78, NOW() - INTERVAL '2 days'),
(NULL, '중소기업 면접에서 물어보면 좋은 것들', '복리후생 얼마나 되는지, 연차는 실제로 쓸 수 있는지, 야근은 어떻게 되는지 꼭 물어보세요. 솔직하게 대답 안 하면 빨간불입니다.', '중소기업', 92, NOW() - INTERVAL '3 days'),
(NULL, '중소기업 대표 바뀌면 다 바뀌나요?', '대표가 갑자기 바뀌었는데 회사 방향이 완전히 달라질 것 같아서 불안합니다. 다들 경험 있으신가요?', '중소기업', 47, NOW() - INTERVAL '4 days'),
(NULL, '매출 100억 이하 회사 복지 현실', '4대 보험만 있고 식대는 현금으로 주는데 이게 일반적인가요? 처음 취업이라 기준을 모르겠어요.', '중소기업', 63, NOW() - INTERVAL '5 days'),
(NULL, '중소기업 팀장 역할 너무 힘들어요', '팀원 5명 관리에 실무도 다 해야 하고, 위에선 실적 요구하고... 팀장 수당은 월 30만원이에요. 이게 맞나요?', '중소기업', 88, NOW() - INTERVAL '6 days'),
(NULL, '중소기업에서 대기업 이직 팁', '저는 중소기업 3년 후 대기업 이직 성공했습니다. 핵심은 이직하려는 직무의 언어로 포트폴리오 만드는 것이었어요.', '중소기업', 116, NOW() - INTERVAL '7 days'),
(NULL, '퇴직금 안 주는 회사 신고 방법', '1년 이상 다녔는데 퇴직금 안 준다고 합니다. 노동부 신고하면 실제로 받을 수 있나요?', '중소기업', 134, NOW() - INTERVAL '8 days'),
(NULL, '중소기업 업무 시스템 너무 구식이에요', '아직도 엑셀로 다 관리하고 전산화가 전혀 안 돼있어요. 대기업 출신 이직자는 다 적응 못하고 나가더라고요.', '중소기업', 71, NOW() - INTERVAL '9 days'),
(NULL, '연봉 3000 중소 vs 3500 스타트업', '안정성이냐 성장 가능성이냐 고민 중입니다. 어떻게 선택하셨나요?', '중소기업', 95, NOW() - INTERVAL '10 days'),
(NULL, '중소기업 대표 사생활 침해가 심해요', '카카오톡으로 밤에도 연락 오고 주말에도 업무 지시합니다. 이게 불법인가요?', '중소기업', 107, NOW() - INTERVAL '11 days'),
(NULL, '중소기업 재직 중 이직 준비 어떻게 하세요?', '퇴근 후에만 준비할 수 있는데 에너지가 없어요. 다들 어떻게 이직 준비하시나요?', '중소기업', 82, NOW() - INTERVAL '12 days'),
(NULL, '중소기업 명함에 직급 뻥튀기가 심하네요', '직원 10명인데 제 명함에 "수석 연구원"이라고 적혀있어요. 나중에 이력서에 어떻게 쓰나요?', '중소기업', 56, NOW() - INTERVAL '13 days'),
(NULL, '야근 당연시하는 문화 어떻게 바꾸나요', '6시 칼퇴하면 눈치 주는 문화인데 제가 잘못된 건가요? 노동법상 초과근무는 수당 줘야 하는 거 아닌가요?', '중소기업', 119, NOW() - INTERVAL '14 days'),
(NULL, '가족 경영 회사 현실', '오너 가족이 임원인 회사 다니는데 처우 차별이 너무 심합니다. 이런 회사 특징이 있나요?', '중소기업', 98, NOW() - INTERVAL '15 days'),
(NULL, '중소기업 직원 10명 이하 현실', '모든 게 나 혼자 해야 하는 느낌이에요. 마케팅, 기획, 고객 응대, 총무까지. 이게 나한테 도움이 되는 건지 모르겠어요.', '중소기업', 74, NOW() - INTERVAL '16 days'),
(NULL, '세금계산서 안 끊어주는 거래처 대응법', '갑이 우리니까 어떻게 해야 할지 모르겠어요. 이런 상황 법적으로 어떻게 되나요?', '중소기업', 39, NOW() - INTERVAL '17 days'),
(NULL, '중소기업 연봉 2800만원 실수령액', '세금 다 떼면 얼마나 남는지 계산해봤더니 너무 적네요. 이 돈으로 서울에서 혼자 살 수 있을까요?', '중소기업', 88, NOW() - INTERVAL '18 days'),
(NULL, '중소기업 경력직 채용 기준이 뭔가요?', '경력 5년인데 중소기업도 잘 안 불러요. 중소기업 면접에서 원하는 게 뭔지 모르겠습니다.', '중소기업', 43, NOW() - INTERVAL '19 days'),
(NULL, 'IT 중소기업 개발자 처우 현실', '개발 외에 총무, 기획까지 시키는데 이게 맞나요? 연봉은 3500인데 스타트업이랑 비교하면 어떤가요?', '중소기업', 77, NOW() - INTERVAL '20 days'),
(NULL, '중소기업 복지포인트 있는 곳 어딘가요', '대기업처럼 복지포인트 지급하는 중소기업도 있나요? 제 주변엔 다 없더라고요.', '중소기업', 31, NOW() - INTERVAL '21 days'),
(NULL, '중소기업 사장이 직원 험담을 해요', '다른 직원한테 저 험담 하는 걸 들었어요. 이런 경우 어떻게 대처하시나요?', '중소기업', 64, NOW() - INTERVAL '22 days'),
(NULL, '중소기업 계약직 vs 정규직 차이', '입사할 때 1년 계약직으로 들어왔는데 정규직 전환 기준이 없어요. 이런 경우 어떻게 해야 하나요?', '중소기업', 52, NOW() - INTERVAL '23 days'),
(NULL, '성과급 없는 회사 그냥 다닐 이유가 있나요', '연봉 인상도 없고 성과급도 없어요. 그냥 계속 다니면 뭔가 이득이 있을까요?', '중소기업', 86, NOW() - INTERVAL '24 days'),
(NULL, '중소기업 입사 첫날 실망한 것들', '면접 때는 분위기 좋다더니 첫날에 보니 완전 달랐어요. 화장실도 1개고 점심도 각자 해결이었습니다.', '중소기업', 97, NOW() - INTERVAL '25 days'),
(NULL, '중소기업에서 6년 버텼더니 생긴 것들', '전문성, 넓은 경험, 인내심은 확실히 생겼습니다. 연봉이 낮아서 이직할 때 약점이지만 역량은 자신 있어요.', '중소기업', 73, NOW() - INTERVAL '26 days'),
(NULL, '월급날 통장 잔고 확인이 두렵습니다', '이번달도 제날짜에 안 들어왔어요. 3번째인데 이제 진짜 나가야 할까요?', '중소기업', 118, NOW() - INTERVAL '27 days'),
(NULL, '중소기업 회식 거절 방법', '주 2회 회식인 회사인데 도저히 못 따라가겠어요. 어떻게 거절해야 관계 안 상하나요?', '중소기업', 67, NOW() - INTERVAL '28 days'),
(NULL, '중소기업 우리사주 가입할 가치 있나요?', '상장 예정이라고 우리사주 권유하는데 회사 재무상태가 궁금합니다. 어떻게 알아봐야 하나요?', '중소기업', 44, NOW() - INTERVAL '29 days'),
(NULL, '신입사원이 나보다 연봉 높아요', '나중에 들어온 신입이 더 높은 연봉으로 들어왔다고 하더라고요. 이런 경우 어떻게 해야 하나요?', '중소기업', 112, NOW() - INTERVAL '30 days'),
(NULL, '중소기업 자기소개서 어떻게 쓰나요', '대기업 공채용 자소서 형식으로 쓰면 안 된다고 들었는데 중소기업은 어떤 포인트를 봐야 하나요?', '중소기업', 48, NOW() - INTERVAL '31 days'),
(NULL, '중소기업 사장 지인 소개로 들어갔는데', '지인 소개라 더 잘 보이려고 압박이 심해요. 다들 이런 경험 있으신가요?', '중소기업', 59, NOW() - INTERVAL '32 days'),
(NULL, '실적 압박이 너무 심한 회사 탈출법', '목표치가 너무 높아서 매달 압박받아요. 이런 회사는 그냥 빨리 나가는 게 답인가요?', '중소기업', 81, NOW() - INTERVAL '33 days'),
(NULL, '중소기업 경리 혼자 하기 한계', '직원 30명 회사 경리를 혼자 하고 있어요. 세무, 급여, 결산까지. 이게 가능한 일인가요?', '중소기업', 66, NOW() - INTERVAL '34 days'),
(NULL, '업종 다른 중소기업으로 이직 가능할까요', '제조업 중소기업 다니다 IT 서비스 쪽으로 가고 싶은데 가능할까요? 나이는 30대 초반입니다.', '중소기업', 54, NOW() - INTERVAL '35 days'),
(NULL, '퇴직하면 다음 직장 잡을 때까지 생계가 걱정돼요', '실업급여 받으면서 이직 준비하려는데 현실적으로 얼마나 걸릴까요?', '중소기업', 93, NOW() - INTERVAL '36 days'),
(NULL, '중소기업 대리 승진 기준이 없어요', '입사 3년 됐는데 승진 얘기가 없어요. 먼저 말 꺼내야 하나요?', '중소기업', 45, NOW() - INTERVAL '37 days'),
(NULL, '명절 상여금 없는 회사도 있나요', '대기업은 상여금이 기본인 줄 알았는데 우리 회사는 없어요. 이게 합법인가요?', '중소기업', 72, NOW() - INTERVAL '38 days'),
(NULL, '중소기업 재직 중 자격증 취득 전략', '회사 다니면서 어떤 자격증 따면 이직에 도움이 될까요? 직무는 마케팅입니다.', '중소기업', 58, NOW() - INTERVAL '39 days'),
(NULL, '중소기업 교육 지원 받은 분 계신가요', '대기업은 교육비 지원이 많다는데 중소기업에서도 받으신 분 계세요?', '중소기업', 34, NOW() - INTERVAL '40 days'),
(NULL, '야근비 안 주는 회사 신고 어디다 하나요', '근로계약서에 포괄임금제 없는데 야근비를 안 줘요. 어디서 신고하면 되나요?', '중소기업', 126, NOW() - INTERVAL '41 days'),
(NULL, '중소기업 영업직 현실', '고객 갑질에 사장 갑질까지... 사방이 갑입니다. 그래도 인센티브 때문에 버티고 있어요.', '중소기업', 79, NOW() - INTERVAL '42 days'),
(NULL, '중소기업 해외 출장비 정산이 너무 복잡해요', '해외 출장 가면 영수증 다 챙겨야 하는데 한도도 너무 낮아요. 이런 회사 많은가요?', '중소기업', 41, NOW() - INTERVAL '43 days'),
(NULL, '중소기업 이직 결정한 결정적 계기', '오늘 대표한테 "월급이 아깝다"는 말 들었습니다. 내일 사직서 씁니다.', '중소기업', 198, NOW() - INTERVAL '44 days'),
(NULL, '중소기업 재무제표 보는 법', '이직할 때 회사 재무상태 확인하고 싶은데 어디서 어떻게 볼 수 있나요?', '중소기업', 87, NOW() - INTERVAL '45 days'),
(NULL, '중소기업 직원 복지 개선 어떻게 제안하나요', '대표한테 복지 개선 얘기하고 싶은데 어떻게 접근하면 좋을까요?', '중소기업', 43, NOW() - INTERVAL '46 days'),
(NULL, '중소기업 다니다 공무원 준비 중입니다', '안정성 때문에 공무원으로 방향 바꿨어요. 다들 어떻게 생각하세요?', '중소기업', 67, NOW() - INTERVAL '47 days'),
(NULL, '중소기업 좋은 점도 있더라고요', '빠른 의사결정, 다양한 업무 경험, 대표와 직접 소통. 단점만 있는 건 아닌 것 같아요.', '중소기업', 52, NOW() - INTERVAL '48 days'),
(NULL, '중소기업 10년차 부장님 연봉이 저랑 별 차이 안 나요', '연차와 직급에 비해 연봉 차이가 너무 작아요. 이 회사에서 미래가 없는 것 같아요.', '중소기업', 94, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '스타트업 스톡옵션 실제로 받은 분 계신가요', '입사할 때 스톡옵션 준다고 했는데 실제로 받은 분 있나요? 계약서에 어떻게 명시돼 있어야 하나요?', '스타트업', 89, NOW() - INTERVAL '1 day'),
(NULL, '시리즈 A 받은 스타트업 입사해도 될까요', '요즘 스타트업 투자 분위기가 안 좋은데 시리즈 A면 어느 정도 안정된 건가요?', '스타트업', 74, NOW() - INTERVAL '2 days'),
(NULL, '스타트업에서 1년 만에 팀장됐습니다', '빠르게 성장한다는 게 이런 거구나 싶었어요. 그런데 경험 없이 팀장 하니까 막막한 점도 많아요.', '스타트업', 103, NOW() - INTERVAL '3 days'),
(NULL, '스타트업 갑작스러운 구조조정 경험담', '어제 잘 다니다가 오늘 갑자기 팀 전체 해고 통보 받았습니다. 이런 경우 법적으로 어떻게 대응하나요?', '스타트업', 157, NOW() - INTERVAL '4 days'),
(NULL, '스타트업 창업자 마인드셋이 싫어요', '"주인의식"이라는 이름으로 야근을 당연시하고 연봉은 시장가보다 낮게 줍니다. 이게 맞나요?', '스타트업', 134, NOW() - INTERVAL '5 days'),
(NULL, '유니콘 스타트업 다녀봤는데 솔직 후기', '겉보기엔 화려한데 내부는 정치가 엄청나요. 스타트업 특유의 수평 문화는 규모 커지면 사라지더라고요.', '스타트업', 118, NOW() - INTERVAL '6 days'),
(NULL, '스타트업 시리즈 C인데 IPO 가능성 어떻게 판단하나요', '재직 중인 스타트업이 시리즈 C까지 받았는데 상장까지 가는 회사가 몇 %나 될까요?', '스타트업', 67, NOW() - INTERVAL '7 days'),
(NULL, '스타트업 CTO가 너무 독단적이에요', '의견 제시하면 무조건 묵살하고 본인 방식만 고집해요. 개발자로서 어떻게 해야 할까요?', '스타트업', 88, NOW() - INTERVAL '8 days'),
(NULL, '스타트업 vs 대기업 3년 후 비교', '스타트업 3년, 그 후 대기업 이직. 솔직히 연봉은 대기업이 압도적이고 성장은 스타트업이 빨랐어요.', '스타트업', 142, NOW() - INTERVAL '9 days'),
(NULL, '스타트업 재직 중 이직 타이밍 언제가 좋을까요', '2년 다녔는데 성장이 느려지는 느낌이에요. 지금 나가는 게 나을까요?', '스타트업', 76, NOW() - INTERVAL '10 days'),
(NULL, 'OKR 도입했는데 현실은', '분기마다 OKR 쓰는데 목표 설정부터 평가까지 애매해요. 실제로 잘 활용하는 회사 있나요?', '스타트업', 59, NOW() - INTERVAL '11 days'),
(NULL, '스타트업 마케터 연봉 현실', '마케터 3년차인데 스타트업 연봉이 생각보다 낮아요. 시장 평균이 어떻게 되나요?', '스타트업', 84, NOW() - INTERVAL '12 days'),
(NULL, '스타트업 대표가 갑자기 사라졌어요', '대표가 연락이 안 된 지 2주째입니다. 급여도 안 들어왔는데 어떻게 해야 하나요?', '스타트업', 173, NOW() - INTERVAL '13 days'),
(NULL, '리모트워크 스타트업 진짜 좋은가요', '완전 리모트인 스타트업 오퍼 받았는데 팀 문화, 협업 방식이 걱정됩니다.', '스타트업', 93, NOW() - INTERVAL '14 days'),
(NULL, '스타트업 HR 직무 어때요', '스타트업에서 HR하면 채용, 문화, 총무 다 해야 한다고 하던데 현실이 어떤가요?', '스타트업', 48, NOW() - INTERVAL '15 days'),
(NULL, '스타트업 피벗 후 살아남은 경험', '우리 회사가 두 번 피벗했는데 두 번 다 살아남았어요. 피벗 과정에서 배운 것들이 많습니다.', '스타트업', 96, NOW() - INTERVAL '16 days'),
(NULL, '스타트업 연봉 재협상 어떻게 하나요', '입사 1년 지났는데 인상 얘기가 없어요. 스타트업에서 먼저 얘기 꺼내도 되나요?', '스타트업', 71, NOW() - INTERVAL '17 days'),
(NULL, '투자 유치 실패한 스타트업 다니는데', '런웨이 3개월 남았다는 소리 들었어요. 지금 이직 준비해야 할까요?', '스타트업', 144, NOW() - INTERVAL '18 days'),
(NULL, '스타트업 개발자 성장 속도 빠른가요', '대기업 개발자 친구보다 내가 더 많이 배우는 것 같은데 맞는 건지 모르겠어요.', '스타트업', 82, NOW() - INTERVAL '19 days'),
(NULL, '스타트업 PM 직무 솔직 후기', '기획, 데이터 분석, 개발 소통, 디자인 리뷰... 진짜 다 해야 합니다. 그래도 재밌어요.', '스타트업', 107, NOW() - INTERVAL '20 days'),
(NULL, '스타트업 번아웃 어떻게 극복하셨나요', '입사 8개월만에 번아웃 왔어요. 열정적으로 일했는데 갑자기 무기력해졌습니다.', '스타트업', 129, NOW() - INTERVAL '21 days'),
(NULL, '외국계 스타트업 vs 국내 스타트업 비교', '영어로 일하는 것 자체는 좋은데 한국 상황과 안 맞는 의사결정이 많아요.', '스타트업', 63, NOW() - INTERVAL '22 days'),
(NULL, '스타트업 디자이너 혼자 다 해야 하나요', '개발자 5명에 디자이너 저 혼자예요. UI, UX, 브랜딩 다 하는데 맞는 환경인가요?', '스타트업', 87, NOW() - INTERVAL '23 days'),
(NULL, '스타트업 수습기간에 잘린 경험담', '3개월 수습 끝나기 직전에 갑자기 "핏이 안 맞는다"고 했어요. 이게 합법인가요?', '스타트업', 138, NOW() - INTERVAL '24 days'),
(NULL, '스타트업 복지가 화려하면 의심해야 하나요', '스낵바, 탄력근무, 리프레시 휴가... 복지는 좋은데 연봉이 낮아요. 이게 다 미끼인가요?', '스타트업', 78, NOW() - INTERVAL '25 days'),
(NULL, '스타트업 데이터 직군 커리어 쌓기', '스타트업에서 DA로 시작해서 DS, 그다음 DE까지 가능한가요?', '스타트업', 54, NOW() - INTERVAL '26 days'),
(NULL, '스타트업 고성과자 대우가 다를까요', '대기업은 고성과자라도 밴드가 있어서 한계가 있다는데 스타트업은 다를까요?', '스타트업', 69, NOW() - INTERVAL '27 days'),
(NULL, '스타트업 공동창업자랑 싸우는 거 봤어요', '대표들이 사무실에서 큰소리로 싸우는 걸 목격했어요. 이런 회사 나가야 하나요?', '스타트업', 97, NOW() - INTERVAL '28 days'),
(NULL, '스타트업 장기근속 장점이 있나요', '3년 이상 다니는 분들이 드물던데 오래 다니면 뭔가 이점이 있나요?', '스타트업', 44, NOW() - INTERVAL '29 days'),
(NULL, '스타트업 인턴 경험 이직에 도움 되나요', '스타트업 인턴 6개월 했는데 대기업 서류 통과에 도움이 될까요?', '스타트업', 61, NOW() - INTERVAL '30 days'),
(NULL, '스타트업 법인카드 사용 기준이 모호해요', '어디까지 법인카드 쓸 수 있는지 기준이 없어요. 다들 어떻게 하세요?', '스타트업', 37, NOW() - INTERVAL '31 days'),
(NULL, '스타트업에서 MBA 지원해주는 곳 있나요', '스타트업 다니면서 MBA 생각 중인데 회사 지원이 가능한 데가 있나요?', '스타트업', 43, NOW() - INTERVAL '32 days'),
(NULL, '스타트업 빠른 성장 vs 워라밸 고민', '성장 속도 빠른 스타트업이냐, 워라밸 좋은 중견기업이냐... 30대 초반에 어떤 선택이 나을까요?', '스타트업', 115, NOW() - INTERVAL '33 days'),
(NULL, '스타트업 투자자 데이터룸 보는 법', '실사 대응해봤는데 투자자들이 뭘 중점적으로 보는지 공유드립니다.', '스타트업', 79, NOW() - INTERVAL '34 days'),
(NULL, '핀테크 스타트업 규제 때문에 힘들어요', '금융 규제 대응이 너무 복잡해요. 스타트업이 이걸 어떻게 감당하나요?', '스타트업', 52, NOW() - INTERVAL '35 days'),
(NULL, '스타트업 1호 직원으로 입사했는데', '모든 걸 만들어가야 하니까 힘들지만 재밌기도 해요. 창업자와 사이가 좋으면 보람있습니다.', '스타트업', 88, NOW() - INTERVAL '36 days'),
(NULL, '스타트업 해외 진출 팀에 합류했어요', '싱가포르 법인 만드는 프로젝트에 참여 중인데 이런 경험 커리어에 얼마나 도움될까요?', '스타트업', 71, NOW() - INTERVAL '37 days'),
(NULL, '스타트업 채용 담당자 솔직 후기', '좋은 인재 뽑기가 너무 어려워요. 연봉 경쟁력이 없으니 결국 문화와 성장 가능성으로 어필해야 하는데 쉽지 않아요.', '스타트업', 64, NOW() - INTERVAL '38 days'),
(NULL, '스타트업 운영 악화 신호 어떻게 아나요', '갑자기 야근이 늘고 분위기가 어두워졌어요. 회사가 어렵다는 신호를 어떻게 감지하나요?', '스타트업', 136, NOW() - INTERVAL '39 days'),
(NULL, '스타트업에서 오퍼레이션 직군 성장 가능성', '운영/물류 담당인데 스타트업에서 이 직군이 성장할 수 있는 방향이 있을까요?', '스타트업', 48, NOW() - INTERVAL '40 days'),
(NULL, '스타트업 대표가 매일 아침 동기부여 연설해요', '처음엔 좋았는데 이제는 피곤해요. 이게 문화 맞나요, 아니면 이상한 건가요?', '스타트업', 83, NOW() - INTERVAL '41 days'),
(NULL, '스타트업 글로벌 팀과 협업하는 현실', '슬랙으로 미국팀이랑 협업하는데 시차 때문에 야근이 기본이에요. 이게 글로벌 경험인가요?', '스타트업', 74, NOW() - INTERVAL '42 days'),
(NULL, '스타트업 콘텐츠 마케터 성장 경로', '블로그, SNS, 광고 다 혼자 하는데 전문성을 어디에 집중해야 할지 모르겠어요.', '스타트업', 56, NOW() - INTERVAL '43 days'),
(NULL, '시드 단계 스타트업 입사 무모한가요', '팀 5명인 시드 스타트업 오퍼 받았는데 리스크가 너무 클까요?', '스타트업', 92, NOW() - INTERVAL '44 days'),
(NULL, '스타트업 근무환경 체크리스트', '오피스 환경, 장비, 복지 말고 내부적으로 꼭 확인해야 할 것들이 뭐가 있을까요?', '스타트업', 101, NOW() - INTERVAL '45 days'),
(NULL, '스타트업 창업 경험 후 재취업 어때요', '1년 창업했다가 접고 재취업 준비 중인데 경력으로 인정받을 수 있을까요?', '스타트업', 118, NOW() - INTERVAL '46 days'),
(NULL, '스타트업 개발팀장 연봉 협상 팁', '팀장 제안 받았는데 연봉을 얼마나 요구하면 될지 모르겠어요. 시장가가 궁금합니다.', '스타트업', 67, NOW() - INTERVAL '47 days'),
(NULL, '스타트업 폐업할 때 직원은 어떻게 되나요', '런웨이 소진되면 직원들 급여는 어떻게 처리되나요? 체당금 신청은 어떻게 하나요?', '스타트업', 149, NOW() - INTERVAL '48 days'),
(NULL, '스타트업 B2B vs B2C 어느 쪽이 좋나요', '커리어 방향 잡을 때 B2B와 B2C 스타트업 중 어느 쪽이 더 배울 게 많을까요?', '스타트업', 73, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '프리랜서 시작 1년 솔직 후기', '수입은 직장 다닐 때보다 많아졌는데 불안감이 항상 있어요. 다음 프로젝트 걱정을 달고 살게 됩니다.', '프리랜서', 98, NOW() - INTERVAL '1 day'),
(NULL, '프리랜서 세금 신고 어떻게 하세요?', '종합소득세 신고 처음인데 어렵게 느껴져요. 세무사 쓰는 분들도 많은가요?', '프리랜서', 87, NOW() - INTERVAL '2 days'),
(NULL, '프리랜서 단가 협상 어떻게 하시나요', '클라이언트가 단가를 너무 낮게 제시하면 어떻게 대응하세요? 협상 팁 공유해주세요.', '프리랜서', 112, NOW() - INTERVAL '3 days'),
(NULL, '프리랜서 국민연금 안 내도 되나요', '지역가입자로 내야 하는 건 알겠는데 금액이 너무 많아요. 줄이는 방법 있나요?', '프리랜서', 76, NOW() - INTERVAL '4 days'),
(NULL, '클라이언트가 갑자기 계약 파기했어요', '계약서 있는데도 갑자기 그냥 취소한다고 해요. 법적으로 어떻게 대응할 수 있나요?', '프리랜서', 134, NOW() - INTERVAL '5 days'),
(NULL, '프리랜서 개발자 월 수입 공유해드려요', '경력 7년, 월 단가 600~700만원 정도 받습니다. 세금 떼면 실수령은 좀 줄어들지만 직장보다 많아요.', '프리랜서', 143, NOW() - INTERVAL '6 days'),
(NULL, '프리랜서 계약서 필수 조항이 뭐가 있나요', '처음 계약서 쓰는데 꼭 넣어야 할 내용이 뭔지 모르겠어요.', '프리랜서', 94, NOW() - INTERVAL '7 days'),
(NULL, '프리랜서 실업급여 받을 수 있나요', '프리랜서는 실업급여 대상이 아닌 건가요? 예술인 고용보험은 들어뒀는데 어떻게 되나요?', '프리랜서', 108, NOW() - INTERVAL '8 days'),
(NULL, '프리랜서 포트폴리오 어떻게 관리하세요', 'Notion, Behance, 개인 사이트... 어디에 올리는 게 효과적인가요?', '프리랜서', 67, NOW() - INTERVAL '9 days'),
(NULL, '프리랜서 건강보험료 줄이는 법', '직장 잃고 지역가입자 되니 건강보험료가 너무 많이 나와요. 합법적으로 줄이는 방법 있나요?', '프리랜서', 119, NOW() - INTERVAL '10 days'),
(NULL, '프리랜서 클라이언트 구하는 채널', '크몽, 숨고, 링크드인, 직접 영업... 어느 채널이 가장 효과적인가요?', '프리랜서', 88, NOW() - INTERVAL '11 days'),
(NULL, '프리랜서 번아웃 어떻게 극복하나요', '혼자 일하다 보니 번아웃 왔을 때 회복이 더 힘든 것 같아요. 다들 어떻게 관리하세요?', '프리랜서', 96, NOW() - INTERVAL '12 days'),
(NULL, '프리랜서 장기 계약 vs 단기 프로젝트', '6개월 이상 장기 계약이 안정적인지, 다양한 단기 프로젝트가 경험상 좋은지 의견 부탁드려요.', '프리랜서', 72, NOW() - INTERVAL '13 days'),
(NULL, '프리랜서 5년차 후회하는 점', '처음에 단가를 너무 낮게 불렀어요. 한번 낮추면 올리기가 너무 어렵더라고요.', '프리랜서', 104, NOW() - INTERVAL '14 days'),
(NULL, '프리랜서 홈오피스 세금 공제 가능한가요', '집에서 일하는데 월세나 인터넷 비용을 경비로 처리할 수 있나요?', '프리랜서', 81, NOW() - INTERVAL '15 days'),
(NULL, '프리랜서 번역가 수입 현실', '영한 번역 프리랜서인데 수입이 들쑥날쑥해요. 안정적으로 일감 구하는 방법이 있나요?', '프리랜서', 58, NOW() - INTERVAL '16 days'),
(NULL, '디자이너 프리랜서로 전향했습니다', '대행사 3년 다니다 독립했어요. 처음 6개월이 제일 힘들었고 지금은 안정됐습니다.', '프리랜서', 127, NOW() - INTERVAL '17 days'),
(NULL, '프리랜서 PM 가능한가요', '기획자로 프리랜서 할 수 있나요? 개발자나 디자이너 말고 기획 프리랜서 시장이 있는지 궁금해요.', '프리랜서', 63, NOW() - INTERVAL '18 days'),
(NULL, '클라이언트 돈 안 주면 어떻게 하나요', '작업 완료 후 3개월째 미지급이에요. 내용증명 보냈는데 계속 미루고 있어요.', '프리랜서', 148, NOW() - INTERVAL '19 days'),
(NULL, '프리랜서 개인사업자 등록 해야 하나요', '프리랜서 시작하려는데 개인사업자 등록 필수인가요? 안 하면 어떻게 되나요?', '프리랜서', 91, NOW() - INTERVAL '20 days'),
(NULL, '프리랜서 월 소득 목표 어떻게 잡으세요', '안정적인 직장 때보다 2배 이상 벌어야 의미있다고 생각하는데 현실적으로 가능한가요?', '프리랜서', 84, NOW() - INTERVAL '21 days'),
(NULL, '프리랜서 비수기 어떻게 버티나요', '1분기가 유독 일이 없는데 다들 비수기 어떻게 대비하시나요?', '프리랜서', 76, NOW() - INTERVAL '22 days'),
(NULL, '프리랜서 영상 편집 단가 적정선', '유튜브 영상 편집 프리랜서인데 분당 얼마를 받는 게 적정한가요?', '프리랜서', 69, NOW() - INTERVAL '23 days'),
(NULL, '프리랜서도 퇴직연금 준비할 수 있나요', 'IRP 같은 걸로 노후 준비 하시는 프리랜서 분들 있나요? 어떻게 운영하세요?', '프리랜서', 88, NOW() - INTERVAL '24 days'),
(NULL, '글쓰기 프리랜서 현실', '콘텐츠 라이터로 프리랜서 하는데 단가가 너무 낮아요. 글 한 편에 얼마를 받는 게 맞나요?', '프리랜서', 72, NOW() - INTERVAL '25 days'),
(NULL, '프리랜서 계약 해지 통보 기간', '클라이언트가 갑자기 계약 종료 통보 했어요. 계약서에 명시된 기간보다 짧게 통보하면 어떻게 되나요?', '프리랜서', 95, NOW() - INTERVAL '26 days'),
(NULL, '프리랜서 전문 플랫폼 추천해주세요', '크몽 말고 다른 프리랜서 플랫폼 써보신 분 있나요? 업종별로 다를 것 같아서요.', '프리랜서', 83, NOW() - INTERVAL '27 days'),
(NULL, '프리랜서 마케터 월 단가 공유', '퍼포먼스 마케터 5년차인데 프리랜서 전향 고려 중입니다. 현실적인 단가가 어떻게 되나요?', '프리랜서', 117, NOW() - INTERVAL '28 days'),
(NULL, '프리랜서 일 안 들어올 때 불안 관리법', '3주째 새 계약이 없어요. 불안감 관리 어떻게 하시나요?', '프리랜서', 109, NOW() - INTERVAL '29 days'),
(NULL, '프리랜서 UX 리서처 있나요', 'UX 리서처를 프리랜서로 할 수 있나요? 이 직군은 프리랜서 시장이 있는 편인가요?', '프리랜서', 54, NOW() - INTERVAL '30 days'),
(NULL, '프리랜서 계약서 없이 일했다가 낭패', '구두 합의만 하고 일했다가 돈을 못 받았어요. 다들 꼭 계약서 쓰세요.', '프리랜서', 156, NOW() - INTERVAL '31 days'),
(NULL, '프리랜서 월 200만원 이상 벌기 어렵나요', '처음 시작하는데 현실적으로 월 200 이상 가능한가요?', '프리랜서', 91, NOW() - INTERVAL '32 days'),
(NULL, '프리랜서 해외 클라이언트와 일하는 법', '업워크, 파이버... 어떻게 시작하면 될까요? 영어가 유창하지 않아도 되나요?', '프리랜서', 106, NOW() - INTERVAL '33 days'),
(NULL, '사진 작가 프리랜서 단가', '제품 사진, 행사 사진 찍는 프리랜서인데 단가 책정이 어렵습니다. 기준이 있나요?', '프리랜서', 62, NOW() - INTERVAL '34 days'),
(NULL, '프리랜서 고정 거래처 만들기', '매번 새 클라이언트 찾는 게 피로해서 장기 거래처를 만들고 싶어요. 어떻게 관계를 유지하세요?', '프리랜서', 97, NOW() - INTERVAL '35 days'),
(NULL, '프리랜서 세금 얼마나 나오나요', '연수입 4000만원이면 세금이 얼마나 나올까요? 공제항목은 어떻게 챙겨야 하나요?', '프리랜서', 128, NOW() - INTERVAL '36 days'),
(NULL, '프리랜서 면접 준비 어떻게 하나요', '프리랜서 계약 전에 클라이언트와 미팅이 있는데 어떻게 준비해야 할까요?', '프리랜서', 58, NOW() - INTERVAL '37 days'),
(NULL, '프리랜서 하면서 결혼 어렵나요', '불안정한 수입 때문에 결혼 생각이 막막합니다. 프리랜서로 결혼하신 분들 조언 부탁드려요.', '프리랜서', 119, NOW() - INTERVAL '38 days'),
(NULL, '프리랜서 스트레스 관리법', '혼자 일하다 보니 스트레스 받아도 터놓을 데가 없어요. 다들 어떻게 하세요?', '프리랜서', 88, NOW() - INTERVAL '39 days'),
(NULL, '프리랜서 재취업 어렵나요', '3년 프리랜서 하다가 다시 회사 들어가려는데 공백이 문제가 되나요?', '프리랜서', 104, NOW() - INTERVAL '40 days'),
(NULL, '프리랜서 코딩 강사 단가', '온라인 코딩 강의 제작 외주 받는데 단가 협상을 어떻게 해야 할까요?', '프리랜서', 56, NOW() - INTERVAL '41 days'),
(NULL, '프리랜서 인맥 없어도 가능한가요', '전 직장 인맥 없이 처음부터 시작하는데 현실적으로 어떻게 클라이언트를 찾아야 하나요?', '프리랜서', 83, NOW() - INTERVAL '42 days'),
(NULL, '프리랜서 계약 금액 입금 확인 전 작업 시작하나요', '선금 없이 먼저 작업하다가 낭패 본 적 있으세요? 어떻게 하는 게 안전한가요?', '프리랜서', 97, NOW() - INTERVAL '43 days'),
(NULL, '프리랜서 SNS 마케팅 효과 있나요', '링크드인, 인스타그램으로 셀프 마케팅 하시는 분들 효과 있나요?', '프리랜서', 64, NOW() - INTERVAL '44 days'),
(NULL, '프리랜서 법인 전환 고려 중입니다', '연매출 1억 넘어서 법인 전환 생각 중인데 장단점이 어떻게 될까요?', '프리랜서', 112, NOW() - INTERVAL '45 days'),
(NULL, '프리랜서 책임 보험 드시나요', '작업 실수로 클라이언트 손해가 났을 때를 대비한 보험이 있나요?', '프리랜서', 47, NOW() - INTERVAL '46 days'),
(NULL, '프리랜서 명함 어떻게 만드세요', '직함을 뭐라고 써야 할지 모르겠어요. 그냥 이름이랑 분야만 써도 되나요?', '프리랜서', 39, NOW() - INTERVAL '47 days'),
(NULL, '프리랜서 일정 관리 어떻게 하세요', '여러 클라이언트 프로젝트를 동시에 진행할 때 일정 충돌 어떻게 관리하시나요?', '프리랜서', 76, NOW() - INTERVAL '48 days'),
(NULL, '프리랜서 전향 후 가장 힘든 점', '돈보다 외로움이 제일 힘들었어요. 혼자 일하는 게 이렇게 외로운 줄 몰랐습니다.', '프리랜서', 131, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '취업 준비 2년만에 대기업 합격했습니다', '포기하지 말고 계속 도전하세요. 저도 68번 서류 떨어지고 결국 됐습니다.', '취업·이직', 247, NOW() - INTERVAL '1 day'),
(NULL, '이직 면접에서 "현재 연봉이 얼마세요?" 어떻게 대답하나요', '솔직하게 말하면 손해인지, 높게 말하면 거짓말인지... 어떻게 대답하는 게 좋을까요?', '취업·이직', 156, NOW() - INTERVAL '2 days'),
(NULL, '이직 준비 중 현 직장 눈치 어떻게 하세요', '면접을 위해 연차를 써야 하는데 팀장한테 들킬까봐 걱정이에요.', '취업·이직', 134, NOW() - INTERVAL '3 days'),
(NULL, '경력직 이직 시 레퍼런스 체크 두렵습니다', '전 직장 상사와 사이가 안 좋았는데 레퍼런스 체크 대상이 되면 어떻게 하나요?', '취업·이직', 97, NOW() - INTERVAL '4 days'),
(NULL, '자소서 한달 동안 썼는데 서류 탈락 이유가 뭘까요', '스펙은 평균 이상인 것 같은데 계속 서류에서 떨어져요. 자소서 첨삭 서비스 효과 있나요?', '취업·이직', 112, NOW() - INTERVAL '5 days'),
(NULL, '면접에서 "마지막으로 하고 싶은 말" 어떻게 하세요', '항상 이 질문에서 당황하는데 어떻게 답하는 게 좋을까요?', '취업·이직', 89, NOW() - INTERVAL '6 days'),
(NULL, '이직할 때 연봉 30% 올리기 가능한가요', '현재 3500인데 5000 이상 받고 이직한 분 있으신가요? 현실적으로 가능한지 궁금합니다.', '취업·이직', 143, NOW() - INTERVAL '7 days'),
(NULL, '취업 공백기 이력서에 어떻게 쓰나요', '1년 공백이 있는데 면접에서 어떻게 설명하는 게 좋을까요?', '취업·이직', 118, NOW() - INTERVAL '8 days'),
(NULL, '최종면접 탈락 후 피드백 받을 수 있나요', '최종까지 갔다가 떨어졌는데 이유를 알고 싶어요. 직접 문의하는 게 실례인가요?', '취업·이직', 82, NOW() - INTERVAL '9 days'),
(NULL, '헤드헌터 연락 받으면 어떻게 하세요', '링크드인으로 헤드헌터 연락이 왔는데 현직자 입장에서 어떻게 대응하는 게 좋을까요?', '취업·이직', 94, NOW() - INTERVAL '10 days'),
(NULL, '직무 전환 이직 어떻게 해야 하나요', '영업 3년 했는데 기획 직무로 전환하고 싶어요. 전혀 다른 직무로 이직한 분들 어떻게 하셨나요?', '취업·이직', 127, NOW() - INTERVAL '11 days'),
(NULL, '인적성 검사 몇 점 이상이면 합격인가요', 'GSAT, HMAT, 각 회사별 인적성 합격 기준이 궁금합니다.', '취업·이직', 76, NOW() - INTERVAL '12 days'),
(NULL, '이직 후 수습 기간 실패하는 경우 있나요', '이직하고 수습 기간에 적응 못해서 잘리는 경우도 있나요? 수습 잘 버티는 방법이 있을까요?', '취업·이직', 103, NOW() - INTERVAL '13 days'),
(NULL, '면접관이 압박 면접을 해요', '면접에서 "그게 왜 성과예요?" 같은 압박 질문이 쏟아지는데 어떻게 대응해야 하나요?', '취업·이직', 88, NOW() - INTERVAL '14 days'),
(NULL, '공기업 vs 대기업 어느 쪽이 나은가요', '둘 다 합격한 상황입니다. 연봉은 대기업이 높고 안정성은 공기업... 어떻게 선택하셨나요?', '취업·이직', 168, NOW() - INTERVAL '15 days'),
(NULL, '이직 후 전 직장 동료 처우 달라지나요', '이직하고 나서 전 직장 사람들이랑 어떻게 지내세요? 어색해지나요?', '취업·이직', 64, NOW() - INTERVAL '16 days'),
(NULL, '취업 시장이 너무 힘들어요 2026년', '경기 침체에 채용 축소까지... 이제 어떻게 해야 할까요?', '취업·이직', 198, NOW() - INTERVAL '17 days'),
(NULL, '이직 면접 준비 기간 얼마나 필요한가요', '현직 다니면서 이직 준비하는데 보통 얼마나 걸리나요?', '취업·이직', 72, NOW() - INTERVAL '18 days'),
(NULL, '영어 면접 어떻게 준비하셨나요', '외국계 기업 면접에서 영어 면접이 있는데 어떻게 준비하는 게 효과적인가요?', '취업·이직', 84, NOW() - INTERVAL '19 days'),
(NULL, '연봉 협상 vs 입사 거부 기준이 어떻게 되나요', '오퍼 받은 연봉이 기대보다 낮을 때 어디까지 협상해보고 거부해야 할까요?', '취업·이직', 119, NOW() - INTERVAL '20 days'),
(NULL, '서류 합격률 높이는 방법 공유', '저는 직무 키워드 최적화로 서류 합격률이 20%에서 50%로 올랐어요. 핵심은 JD 분석입니다.', '취업·이직', 176, NOW() - INTERVAL '21 days'),
(NULL, '면접 복장 뭐가 좋은가요', 'IT 기업 면접인데 정장이 오히려 어색할까요? 비즈니스 캐주얼로 가는 게 나을까요?', '취업·이직', 57, NOW() - INTERVAL '22 days'),
(NULL, '이직 사유 "연봉 때문에"라고 솔직하게 말해도 되나요', '왜 이직하려고 하냐는 질문에 솔직하게 답하고 싶은데 역효과가 날까요?', '취업·이직', 131, NOW() - INTERVAL '23 days'),
(NULL, '외국계 기업 이직 문화가 많이 다른가요', '외국계 기업으로 이직 고려 중인데 국내 기업과 문화 차이가 체감적으로 얼마나 다른가요?', '취업·이직', 94, NOW() - INTERVAL '24 days'),
(NULL, '이직 후 적응 기간이 얼마나 걸리나요', '새 직장에서 완전히 적응되기까지 얼마나 걸렸나요? 6개월이면 충분한가요?', '취업·이직', 88, NOW() - INTERVAL '25 days'),
(NULL, '포트폴리오 없는 직무는 어떻게 어필하나요', '영업/영업관리 직무인데 포트폴리오 만들기가 애매해요. 어떻게 차별화할 수 있을까요?', '취업·이직', 79, NOW() - INTERVAL '26 days'),
(NULL, '이직 시 직급 협상 가능한가요', '현재 과장인데 이직하면서 차장 타이틀을 받을 수 있나요?', '취업·이직', 96, NOW() - INTERVAL '27 days'),
(NULL, '공채 폐지 이후 채용 어떻게 준비하나요', '수시채용이 대세가 됐는데 직무 역량 준비를 어떻게 해야 할까요?', '취업·이직', 114, NOW() - INTERVAL '28 days'),
(NULL, '이직 면접 중 현 직장 험담하면 안 되나요', '현 직장 문제 때문에 이직하는데 면접에서 어디까지 솔직하게 말해야 하나요?', '취업·이직', 87, NOW() - INTERVAL '29 days'),
(NULL, '30대 중반 이직 늦지 않았나요', '35살에 이직 생각 중인데 나이 때문에 불리한가요?', '취업·이직', 139, NOW() - INTERVAL '30 days'),
(NULL, '합격 취소 통보 받았어요', '최종 합격 후 입사일 앞두고 갑자기 취소 연락이 왔어요. 이게 가능한 건가요?', '취업·이직', 178, NOW() - INTERVAL '31 days'),
(NULL, '이직 후 연봉 후회한 경험 있으세요', '연봉 올려서 이직했는데 실제 처우는 더 나빠진 것 같아요. 다들 비슷한 경험 있나요?', '취업·이직', 93, NOW() - INTERVAL '32 days'),
(NULL, '구직 기간 길어질수록 자존감이 무너져요', '6개월 넘게 구직 중인데 자존감이 바닥입니다. 마음 추스르는 방법이 있을까요?', '취업·이직', 162, NOW() - INTERVAL '33 days'),
(NULL, '채용 공고 JD 해석하는 방법', '공고 보면 모든 게 다 필요한 것처럼 쓰여 있는데 실제로 어떻게 해석해야 하나요?', '취업·이직', 107, NOW() - INTERVAL '34 days'),
(NULL, '이직 시 현 직장에 언제 알리나요', '최종 합격 후에 바로 알려야 하나요? 타이밍을 잘못 잡으면 분위기가 이상해질 것 같아요.', '취업·이직', 121, NOW() - INTERVAL '35 days'),
(NULL, '채용 대행사 통한 지원 불리한가요', '헤드헌터 통해서 지원하면 직접 지원보다 불리한가요?', '취업·이직', 68, NOW() - INTERVAL '36 days'),
(NULL, '이직 후 시용 기간에 연봉 달라지나요', '이직하고 수습 기간엔 연봉 일부만 주는 곳이 있는데 이게 정상인가요?', '취업·이직', 86, NOW() - INTERVAL '37 days'),
(NULL, '면접 후 결과 연락 얼마나 기다려야 하나요', '면접 보고 2주 지났는데 아직 연락이 없어요. 직접 문의해도 될까요?', '취업·이직', 73, NOW() - INTERVAL '38 days'),
(NULL, '이력서에 퇴직 이유 써야 하나요', '단기 퇴직 이력이 있는데 이력서에 퇴직 사유를 미리 써두는 게 나을까요?', '취업·이직', 91, NOW() - INTERVAL '39 days'),
(NULL, '취업 성공 후 슬럼프가 옵니다', '그토록 원하던 회사에 취업했는데 막상 와보니 기대와 달라서 공허해요.', '취업·이직', 134, NOW() - INTERVAL '40 days'),
(NULL, '이직 횟수 많으면 불리한가요', '5년 동안 3번 이직했는데 면접에서 항상 이 부분이 지적돼요.', '취업·이직', 116, NOW() - INTERVAL '41 days'),
(NULL, '인사담당자가 보는 이력서 포인트', 'HR 담당자 관점에서 이력서에서 가장 중요하게 보는 게 뭔지 알려주세요.', '취업·이직', 189, NOW() - INTERVAL '42 days'),
(NULL, '첫 직장 6개월만에 이직 괜찮나요', '너무 힘들어서 나오고 싶은데 6개월은 너무 짧은가요?', '취업·이직', 143, NOW() - INTERVAL '43 days'),
(NULL, '링크드인 프로필 관리 어떻게 하세요', '링크드인으로 이직 기회 온 분 있나요? 어떻게 관리하면 효과적인가요?', '취업·이직', 88, NOW() - INTERVAL '44 days'),
(NULL, '면접 전날 긴장 풀리는 방법', '면접만 생각하면 잠을 못 자요. 다들 어떻게 컨디션 관리하시나요?', '취업·이직', 97, NOW() - INTERVAL '45 days'),
(NULL, '취업 준비생 루틴 공유해드려요', '오전 공부, 오후 자소서, 저녁 운동 루틴으로 멘탈 관리했어요. 취준생 분들 파이팅입니다!', '취업·이직', 213, NOW() - INTERVAL '46 days'),
(NULL, '대기업 공채 vs 경력직 채용 차이', '신입으로 들어가는 것과 경력직으로 들어가는 것의 장단점이 뭔가요?', '취업·이직', 74, NOW() - INTERVAL '47 days'),
(NULL, '면접에서 떨어지는 이유를 모르겠어요', '서류는 잘 통과되는데 면접에서 계속 떨어져요. 뭐가 문제일까요?', '취업·이직', 128, NOW() - INTERVAL '48 days'),
(NULL, '이직 준비 언제부터 하는 게 좋을까요', '현재 다니면서 이직 생각이 있는데 얼마나 일찍부터 준비해야 할까요?', '취업·이직', 84, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '연봉 실수령액 계산 방법 정리해드려요', '연봉 4000만원 기준 실수령 약 286만원, 5000만원은 약 345만원입니다. 4대보험+소득세 계산법 알려드릴게요.', '급여·연봉', 234, NOW() - INTERVAL '1 day'),
(NULL, '연봉 5천 vs 4천 복지 좋은 곳 어느 게 나은가요', '연봉이 낮아도 복지가 좋으면 실질적으로 더 나을 수 있다는데 실제 계산해본 분 있나요?', '급여·연봉', 127, NOW() - INTERVAL '2 days'),
(NULL, '포괄임금제 야근 수당 없는 게 맞나요', '포괄임금제라고 야근해도 수당이 없어요. 이게 합법인가요 불법인가요?', '급여·연봉', 178, NOW() - INTERVAL '3 days'),
(NULL, '연봉 협상 매년 하는 건가요', '입사할 때 협상하고 이후엔 회사가 알아서 올려주는 건지, 매년 다시 협상해야 하는 건지 궁금해요.', '급여·연봉', 94, NOW() - INTERVAL '4 days'),
(NULL, '직군별 연봉 현실 공유 (IT 개발자)', 'ML 엔지니어 5년차 기준 대기업 8000, 스타트업 7000~9000 정도 됩니다. 직군별로 공유해봐요.', '급여·연봉', 198, NOW() - INTERVAL '5 days'),
(NULL, '세전 세후 차이 왜 이렇게 크나요', '연봉 6000인데 실수령이 400도 안 돼요. 세금이 너무 많은 거 아닌가요?', '급여·연봉', 143, NOW() - INTERVAL '6 days'),
(NULL, '성과급 기준이 불투명해요', '매년 성과급 받는데 기준이 뭔지 모르겠어요. 인사평가랑 연동된다는데 어떻게 계산되는 건가요?', '급여·연봉', 116, NOW() - INTERVAL '7 days'),
(NULL, '직급별 연봉 밴드 공유 (대기업)', '사원~부장까지 대략적인 연봉 밴드가 어떻게 되는지 궁금합니다. 본인 회사 기준으로 공유해주세요.', '급여·연봉', 187, NOW() - INTERVAL '8 days'),
(NULL, '연봉 인상률 물가 상승률도 못 따라가요', '물가는 5% 오르는데 연봉 인상은 3%예요. 실질적으로 연봉 삭감 아닌가요?', '급여·연봉', 156, NOW() - INTERVAL '9 days'),
(NULL, '퇴직금 중간 정산 하는 게 나을까요', '퇴직금 중간 정산 신청했는데 나중에 불리할 수 있다는 말을 들었어요. 어떻게 하는 게 좋을까요?', '급여·연봉', 88, NOW() - INTERVAL '10 days'),
(NULL, '야간수당 계산법 알려주세요', '밤 10시 이후 야근은 1.5배 수당이 맞나요? 포괄임금제면 예외인가요?', '급여·연봉', 134, NOW() - INTERVAL '11 days'),
(NULL, '연봉 6000 vs 연봉 5000 + 재택근무', '출퇴근 비용, 시간 절약을 감안하면 재택이 더 유리할 수 있다는데 계산해볼게요.', '급여·연봉', 173, NOW() - INTERVAL '12 days'),
(NULL, '국민연금 더 많이 내면 나중에 더 받나요', '국민연금 상한선 이상 내면 의미 없다는데 맞나요?', '급여·연봉', 97, NOW() - INTERVAL '13 days'),
(NULL, '복지포인트 세금 내야 하나요', '회사에서 복지포인트 주는데 이게 소득세 과세 대상인가요?', '급여·연봉', 112, NOW() - INTERVAL '14 days'),
(NULL, '연봉 협상 실패 후기', '"본인이 원하는 연봉 말씀해보세요"라고 해서 5500 불렀더니 갑자기 분위기가 싸해졌어요. 어떻게 해야 했을까요?', '급여·연봉', 141, NOW() - INTERVAL '15 days'),
(NULL, '미지급 임금 신고 후기', '체불 신고 후 실제로 받기까지 얼마나 걸렸는지 경험 공유해드려요. 노동청 절차 설명드릴게요.', '급여·연봉', 167, NOW() - INTERVAL '16 days'),
(NULL, '스톡옵션 세금 어마어마하네요', '스톡옵션 행사했는데 세금으로 반 가까이 나갔어요. 절세 방법이 있나요?', '급여·연봉', 129, NOW() - INTERVAL '17 days'),
(NULL, '업계별 연봉 현실 (금융권)', '은행권 연봉은 과장된 것 같아요. 초봉은 높은데 인상률이 낮아서 10년 후엔 별 차이 없을 수도 있어요.', '급여·연봉', 108, NOW() - INTERVAL '18 days'),
(NULL, '연봉 협상 타이밍이 언제가 좋을까요', '이직 협상이 아니라 재직 중 연봉 인상 요청 타이밍이 언제가 효과적인가요?', '급여·연봉', 83, NOW() - INTERVAL '19 days'),
(NULL, '연봉 3000대 직장인 재테크', '연봉이 많지 않은데 어떻게 재테크해야 할까요? 저축부터 시작해야 하나요?', '급여·연봉', 119, NOW() - INTERVAL '20 days'),
(NULL, '사이닝 보너스 받으면 세금이 얼마나', '이직할 때 사이닝 보너스 2000만원 받았는데 세금이 상당히 나왔어요. 얼마나 나오나요?', '급여·연봉', 94, NOW() - INTERVAL '21 days'),
(NULL, '연봉 1억 넘는 직종이 뭐가 있나요', '일반 직장인 기준으로 어떤 직무, 연차가 되면 1억 넘을 수 있나요?', '급여·연봉', 187, NOW() - INTERVAL '22 days'),
(NULL, '임금 피크제 적용받은 분 어떤가요', '50대 되면 임금 피크제 적용이 시작되는데 실제로 얼마나 줄어드나요?', '급여·연봉', 76, NOW() - INTERVAL '23 days'),
(NULL, '계약직 연봉 정규직보다 높아도 불안해요', '계약직으로 연봉 협상해서 정규직보다 높게 받는데 연장 안 되면 어쩌나 불안합니다.', '급여·연봉', 103, NOW() - INTERVAL '24 days'),
(NULL, '성과 기반 연봉제 직원들 불만이 많아요', '팀 성과 기반이라 본인 노력이 안 반영되는 느낌이에요. 이런 제도 어떻게 생각하세요?', '급여·연봉', 88, NOW() - INTERVAL '25 days'),
(NULL, '이직하면서 연봉 20% 올린 방법', '협상 스크립트부터 타이밍까지 공유해드릴게요. 핵심은 복수의 오퍼를 만드는 것입니다.', '급여·연봉', 234, NOW() - INTERVAL '26 days'),
(NULL, '교통비, 식대 비과세 한도가 어떻게 되나요', '비과세 한도 초과분은 소득세 내야 하는 건가요? 회사 급여명세서 보는 법 알려주세요.', '급여·연봉', 91, NOW() - INTERVAL '27 days'),
(NULL, '연봉 협상 시 다른 회사 오퍼 써도 되나요', '경쟁 오퍼를 레버리지로 쓰는 게 전략상 맞는 건지 아니면 역효과가 날 수 있는지 궁금해요.', '급여·연봉', 147, NOW() - INTERVAL '28 days'),
(NULL, '파트타임 직원 주휴수당 의무인가요', '주 15시간 이상이면 주휴수당 줘야 하는데 안 주는 알바 자리가 너무 많아요.', '급여·연봉', 138, NOW() - INTERVAL '29 days'),
(NULL, '개발자 연봉 거품이라고 생각하시나요', 'AI로 대체될 거라는 얘기가 많은데 지금 개발자 고연봉이 계속 유지될까요?', '급여·연봉', 163, NOW() - INTERVAL '30 days'),
(NULL, '연차수당 안 챙겨주는 회사 많은가요', '연차 다 못 쓰면 수당으로 줘야 하는 건데 그냥 소멸시키는 회사들이 있더라고요.', '급여·연봉', 124, NOW() - INTERVAL '31 days'),
(NULL, '급여명세서 항목 해석이 어려워요', '공제 항목에 뭐가 이렇게 많은지... 급여명세서 보는 법 알려주실 분 있나요?', '급여·연봉', 97, NOW() - INTERVAL '32 days'),
(NULL, '연봉 협상할 때 절대 하면 안 되는 말', '"생활이 어렵다", "전 직장이 얼마였다" 같은 말은 역효과가 납니다. 오직 시장가와 기여도로 얘기하세요.', '급여·연봉', 187, NOW() - INTERVAL '33 days'),
(NULL, '상여금 vs 성과급 차이가 뭔가요', '계약서에 상여금 200%라고 돼 있는데 이게 연봉의 200%인가요, 월급의 200%인가요?', '급여·연봉', 112, NOW() - INTERVAL '34 days'),
(NULL, '프리랜서 vs 정직원 세후 소득 비교', '겉보기 연봉만 비교하면 안 되고 4대보험, 퇴직금, 세금 다 고려해야 실질 비교가 되더라고요.', '급여·연봉', 143, NOW() - INTERVAL '35 days'),
(NULL, '야근 안 하는데 연봉 올리기 어렵나요', '칼퇴하는데 성과 평가에서 불리한 것 같아요. 야근이 없어도 연봉 잘 받는 방법 있나요?', '급여·연봉', 134, NOW() - INTERVAL '36 days'),
(NULL, '퇴직연금 DC형 vs DB형 어느 게 유리한가요', '이직 많은 사람은 DC형이 유리하다는데 실제로 어떻게 다른가요?', '급여·연봉', 118, NOW() - INTERVAL '37 days'),
(NULL, '연봉 협상 이메일 어떻게 써요', '오퍼 받고 이메일로 연봉 협상하는 법 알려주세요. 잘못 쓰면 실례가 될까봐요.', '급여·연봉', 89, NOW() - INTERVAL '38 days'),
(NULL, '기업 규모별 평균 연봉 비교', '대기업, 중견, 중소, 스타트업 신입 평균 연봉이 실제로 얼마나 차이 나나요?', '급여·연봉', 167, NOW() - INTERVAL '39 days'),
(NULL, '연봉 공개가 의무화되면 좋을까요', '미국처럼 채용 공고에 연봉 범위 공개를 의무화하면 어떨까요? 찬반 의견이 궁금합니다.', '급여·연봉', 203, NOW() - INTERVAL '40 days'),
(NULL, '이직 후 연봉 후회하지 않으려면', '처음 오퍼 받았을 때 바로 수락하지 말고 최소 하루는 생각하세요. 후회한 경험 공유합니다.', '급여·연봉', 154, NOW() - INTERVAL '41 days'),
(NULL, '비과세 항목 최대한 활용하는 법', '식대, 교통비, 자가운전보조금... 비과세로 받을 수 있는 항목들 정리해드립니다.', '급여·연봉', 178, NOW() - INTERVAL '42 days'),
(NULL, '연봉 5000이면 서울 생활 가능한가요', '30대 초반에 연봉 5000인데 서울에서 혼자 살면서 저축 가능할까요?', '급여·연봉', 129, NOW() - INTERVAL '43 days'),
(NULL, '팀장 수당이 너무 적어요', '팀장 맡았는데 수당이 월 20만원이에요. 책임은 훨씬 늘었는데 이게 맞나요?', '급여·연봉', 143, NOW() - INTERVAL '44 days'),
(NULL, '연봉 협상 성공률 높이는 팁 총정리', '타이밍, 근거 자료, 협상 멘트까지 실전에서 써먹은 방법 공유해드릴게요.', '급여·연봉', 267, NOW() - INTERVAL '45 days'),
(NULL, '세금 환급 어떻게 받나요', '연말정산 후 환급이 나와야 하는데 오히려 토해냈어요. 왜 그런 건가요?', '급여·연봉', 108, NOW() - INTERVAL '46 days'),
(NULL, '직장인 건강보험료 계산 방법', '연봉이 오르면 건강보험료도 같이 오르는데 어떻게 계산하면 되나요?', '급여·연봉', 82, NOW() - INTERVAL '47 days'),
(NULL, '성과급 없는 대기업 vs 성과급 있는 중견기업', '기본급은 대기업이 높지만 성과급이 없고, 중견기업은 기본이 낮지만 성과급이 큰데 어느 게 나을까요?', '급여·연봉', 136, NOW() - INTERVAL '48 days'),
(NULL, '계약서에 연봉 외 추가 비용 협상하는 법', '사이닝 보너스, 이사비용 지원, 스톡옵션 등 연봉 외 항목 협상하는 법 알려드릴게요.', '급여·연봉', 158, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '직장 상사가 저만 싫어하는 것 같아요', '다른 팀원들은 잘 대해주는데 저한테만 차갑게 대해요. 이유를 모르겠고 직장 가기가 싫어요.', '직장생활', 143, NOW() - INTERVAL '1 day'),
(NULL, '회식 문화 없애고 싶은데 방법이 있나요', '팀 내에서 회식 문화를 바꾸고 싶은데 혼자 말 꺼내기 어려워요. 어떻게 접근하면 될까요?', '직장생활', 112, NOW() - INTERVAL '2 days'),
(NULL, '칼퇴하는데 눈치 안 보이는 법', '정시 퇴근이 너무나 당연한 건데 왜 눈치를 봐야 하는지 모르겠어요. 다들 어떻게 하세요?', '직장생활', 176, NOW() - INTERVAL '3 days'),
(NULL, '직장 내 괴롭힘 신고하면 어떻게 되나요', '상사로부터 언어 폭력을 받고 있는데 신고하면 실제로 보호받을 수 있나요?', '직장생활', 198, NOW() - INTERVAL '4 days'),
(NULL, '점심 혼밥 어떻게 생각하세요', '새로운 팀에서 점심 혼자 먹고 싶은데 분위기상 말하기 어려워요. 혼밥 하시는 분들 어때요?', '직장생활', 134, NOW() - INTERVAL '5 days'),
(NULL, '직장에서 친한 친구 사귀기 어렵나요', '30대에 이직한 회사에서 진짜 친한 사람 사귀기가 쉽지 않네요. 다들 그런가요?', '직장생활', 108, NOW() - INTERVAL '6 days'),
(NULL, '업무 중 실수하면 어떻게 대처하세요', '큰 실수를 해서 팀에 폐를 끼쳤어요. 어떻게 수습하고 신뢰를 회복할 수 있을까요?', '직장생활', 127, NOW() - INTERVAL '7 days'),
(NULL, '워라밸 챙기면서도 성과 잘 내는 방법', '일 잘 하면서도 야근 안 하는 사람들이 있는데 어떻게 하는 건지 궁금해요.', '직장생활', 189, NOW() - INTERVAL '8 days'),
(NULL, '직장 상사한테 반박하면 안 되나요', '상사가 명백히 틀린 말을 해도 반박하면 분위기가 싸해져요. 어떻게 대처해야 할까요?', '직장생활', 167, NOW() - INTERVAL '9 days'),
(NULL, '동료가 내 공을 가로채요', '내가 한 아이디어와 업무를 팀장한테 본인이 한 것처럼 얘기하는 동료가 있어요. 어떻게 대응해야 하나요?', '직장생활', 156, NOW() - INTERVAL '10 days'),
(NULL, '메신저로 업무 지시 밤에 오면 어떻게 하세요', '퇴근 후에도 카톡으로 업무 지시가 오는데 답해야 하나 말아야 하나 항상 고민이에요.', '직장생활', 178, NOW() - INTERVAL '11 days'),
(NULL, '직장 생활 번아웃 신호 알아보는 법', '어느 순간부터 출근하기 싫고, 아무것도 하기 싫어졌어요. 번아웃인가요 아니면 다른 문제인가요?', '직장생활', 143, NOW() - INTERVAL '12 days'),
(NULL, '부서 이동 신청하는 방법', '현재 팀이 너무 맞지 않아서 다른 부서로 가고 싶어요. 어떻게 신청하는 게 좋을까요?', '직장생활', 98, NOW() - INTERVAL '13 days'),
(NULL, '회의에서 말 잘 하는 법', '회의 때 의견을 표현하고 싶은데 말문이 막혀요. 어떻게 개선할 수 있을까요?', '직장생활', 124, NOW() - INTERVAL '14 days'),
(NULL, '직장인 정신건강 관리법', '매일 스트레스가 쌓이는데 퇴근 후 어떻게 해소하고 계세요?', '직장생활', 187, NOW() - INTERVAL '15 days'),
(NULL, '입사 첫날 잘 적응하는 법', '새로운 회사 첫날 어떻게 행동해야 좋은 인상을 줄 수 있나요? 이직 후 적응 팁 알려주세요.', '직장생활', 113, NOW() - INTERVAL '16 days'),
(NULL, '사내 연애 어떻게 생각하세요', '같은 팀은 너무 위험하고 다른 팀은 괜찮지 않을까요? 직장 내 연애 경험 있으신 분 얘기 듣고 싶어요.', '직장생활', 134, NOW() - INTERVAL '17 days'),
(NULL, '신입인데 선배들이 말을 안 가르쳐줘요', '눈치껏 알아서 하라는데 뭘 어떻게 해야 할지 모르겠어요. 이런 환경에서 어떻게 적응하나요?', '직장생활', 107, NOW() - INTERVAL '18 days'),
(NULL, '직장인 점심시간 활용법', '점심시간 1시간이 황금 같은데 어떻게 활용하세요? 공부, 운동, 낮잠 중 뭐가 제일 효율적인가요?', '직장생활', 89, NOW() - INTERVAL '19 days'),
(NULL, '업무 우선순위 설정이 어려워요', '할 일이 너무 많아서 뭐부터 해야 할지 모르겠어요. 업무 우선순위 어떻게 정하세요?', '직장생활', 118, NOW() - INTERVAL '20 days'),
(NULL, '같은 직급 동료보다 일이 몇 배 많아요', '일 잘 한다는 이유로 일이 계속 몰려오는데 어떻게 해야 하나요?', '직장생활', 163, NOW() - INTERVAL '21 days'),
(NULL, '직장 내 험담하는 사람 대처법', '뒷담화를 자주 하는 동료가 있는데 어떻게 대처해야 관계도 안 상하고 나도 보호할 수 있을까요?', '직장생활', 127, NOW() - INTERVAL '22 days'),
(NULL, '재택근무 생산성 유지하는 법', '집에서 일하면 집중이 안 돼요. 재택근무 생산성 높이는 방법 공유해주세요.', '직장생활', 144, NOW() - INTERVAL '23 days'),
(NULL, '직장 상사 생일 챙겨야 하나요', '팀 문화가 생일을 다 챙기는 편인데 상사 생일은 부담이 되더라고요. 어떻게 하세요?', '직장생활', 87, NOW() - INTERVAL '24 days'),
(NULL, '연차 눈치 안 보고 쓰는 방법', '연차를 자유롭게 쓰는 팁이 있나요? 팀장 눈치가 보여서 신청하기 어려워요.', '직장생활', 156, NOW() - INTERVAL '25 days'),
(NULL, '직장 스트레스가 건강에 영향을 주는 것 같아요', '두통, 소화불량이 직장 스트레스 때문인 것 같아요. 다들 어떻게 관리하세요?', '직장생활', 134, NOW() - INTERVAL '26 days'),
(NULL, '업무 외 시간에 공부하는 분들 어떻게 하세요', '퇴근 후 너무 지쳐서 공부가 안 돼요. 자기계발 어떻게 하시는지 궁금합니다.', '직장생활', 118, NOW() - INTERVAL '27 days'),
(NULL, '직장 내 세대 갈등 심한가요', '20대와 40대의 일하는 방식이 너무 달라서 충돌이 잦아요. 어떻게 해결하나요?', '직장생활', 143, NOW() - INTERVAL '28 days'),
(NULL, '직장 생활 10년 배운 것들', '직장 생활 10년차 선배로서 신입들한테 해주고 싶은 말들 공유합니다.', '직장생활', 219, NOW() - INTERVAL '29 days'),
(NULL, '팀장이 되면 뭐가 달라지나요', '팀원에서 팀장이 되면 실제로 어떤 점이 달라지나요? 팀장 하시는 분들 솔직한 후기 부탁드려요.', '직장생활', 97, NOW() - INTERVAL '30 days'),
(NULL, '좋아하는 일 vs 잘 하는 일 뭘 직업으로 해야 하나요', '좋아하는 건 돈이 안 되고, 잘 하는 건 흥미가 없어요. 어떻게 선택하셨나요?', '직장생활', 178, NOW() - INTERVAL '31 days'),
(NULL, '업무 메일 잘 쓰는 방법', '이메일 쓸 때마다 어색한데 좋은 방법이 있나요? 특히 윗사람한테 보낼 때 어렵습니다.', '직장생활', 94, NOW() - INTERVAL '32 days'),
(NULL, '직장에서 인정받는 사람들의 공통점', '일 잘 한다는 말을 듣는 사람들은 어떤 특징이 있나요? 관찰해보면 공통점이 있더라고요.', '직장생활', 198, NOW() - INTERVAL '33 days'),
(NULL, '퇴직하기 전에 꼭 챙겨야 할 것들', '이직이나 퇴직 전에 준비해야 할 것들 정리해드릴게요. 경험자로서 놓치지 마세요.', '직장생활', 213, NOW() - INTERVAL '34 days'),
(NULL, '직장 내 성차별 겪으신 분 있나요', '여성이라는 이유로 불합리한 대우를 받은 경험 공유해주세요. 같이 이야기 나눠봐요.', '직장생활', 167, NOW() - INTERVAL '35 days'),
(NULL, '직장에서 멘토 어떻게 찾나요', '직장 선배 중에 멘토로 삼고 싶은 분이 있는데 어떻게 관계를 만들어가야 할까요?', '직장생활', 88, NOW() - INTERVAL '36 days'),
(NULL, '주 4일제 도입된 회사 다니시는 분', '주 4일제 어때요? 실제로 업무 효율이 좋아졌나요? 단점은 없나요?', '직장생활', 189, NOW() - INTERVAL '37 days'),
(NULL, '직장인 인간관계 최소화 가능한가요', '직장 사람들과 업무 외 관계를 최소화하고 싶은데 이게 가능한가요?', '직장생활', 134, NOW() - INTERVAL '38 days'),
(NULL, '업무 실수 숨기고 싶을 때', '실수를 빨리 보고해야 한다는 건 알지만 너무 무서워서 못 했어요. 어떻게 해야 했을까요?', '직장생활', 143, NOW() - INTERVAL '39 days'),
(NULL, '직장 생활 잘 하는 기준이 뭔가요', '좋은 직장인이 되려면 어떻게 해야 하는 건지 기준을 모르겠어요.', '직장생활', 112, NOW() - INTERVAL '40 days'),
(NULL, '상사한테 칭찬 받으면 기분 좋은 게 당연한가요', '상사 칭찬이 이렇게 기쁜 게 이상한 건지 아니면 다들 그런 건지 궁금합니다.', '직장생활', 78, NOW() - INTERVAL '41 days'),
(NULL, '직장인 건강 관리 어떻게 하세요', '앉아서 일하다 보니 허리, 목 다 망가졌어요. 직장인 건강 관리 팁 공유해주세요.', '직장생활', 134, NOW() - INTERVAL '42 days'),
(NULL, '팀 내 갈등 어떻게 중재하나요', '팀원들 사이에 갈등이 생겼는데 팀장 입장에서 어떻게 중재해야 할지 모르겠어요.', '직장생활', 97, NOW() - INTERVAL '43 days'),
(NULL, '직장에서 절대 하면 안 되는 실수들', '경험상 직장 생활에서 절대 하면 안 되는 것들을 정리해봤어요. 특히 신입들은 필독!', '직장생활', 198, NOW() - INTERVAL '44 days'),
(NULL, '직장 생활 즐겁게 하는 방법', '일이 재미없어도 직장 생활을 즐겁게 할 수 있는 방법이 있을까요?', '직장생활', 123, NOW() - INTERVAL '45 days'),
(NULL, '직장인 자기계발 어떻게 하세요', '퇴근 후 시간을 자기계발에 쓰고 싶은데 지쳐서 힘들어요. 어떻게 루틴을 만들 수 있을까요?', '직장생활', 156, NOW() - INTERVAL '46 days'),
(NULL, '나쁜 회사에서 얻을 수 있는 것들', '나쁜 직장도 배울 게 있다는 말이 맞나요? 힘든 환경에서 어떤 것들을 배울 수 있을까요?', '직장생활', 112, NOW() - INTERVAL '47 days'),
(NULL, '직장인 대화 잘 하는 방법', '직장에서 소통이 잘 안 돼서 답답해요. 대화를 잘 하는 팁이 있을까요?', '직장생활', 87, NOW() - INTERVAL '48 days'),
(NULL, '직장 생활 5년 후 내가 어디 있을까', '지금 하는 일이 5년 후에도 의미 있을지 고민이 됩니다. 커리어 방향을 어떻게 잡아야 할까요?', '직장생활', 143, NOW() - INTERVAL '49 days');
INSERT INTO posts (user_id, title, content, category, likes_count, created_at) VALUES
(NULL, '직장인 여행 어디로 가세요?', '연차 모아서 해외여행 계획 중인데 직장인에게 딱 좋은 여행지 추천해주세요. 비용 대비 만족도 높은 곳으로요.', '자유게시판', 87, NOW() - INTERVAL '1 day'),
(NULL, '직장인이 보는 드라마 추천', '출퇴근 시간에 볼 만한 드라마나 예능 추천해주세요. 직장 스트레스 풀리는 콘텐츠면 더 좋아요.', '자유게시판', 64, NOW() - INTERVAL '2 days'),
(NULL, '30대 초반 직장인 재테크 시작법', '이제 막 재테크 시작하려는데 어디서 시작하면 좋을까요? 주식, 펀드, 저축 중 어디부터 해야 하나요?', '자유게시판', 134, NOW() - INTERVAL '3 days'),
(NULL, '직장인 점심 추천 (혼자 먹기 좋은)', '혼자 점심 먹을 때 어디 가세요? 맛있고 혼밥하기 편한 식당 추천해주세요.', '자유게시판', 72, NOW() - INTERVAL '4 days'),
(NULL, '직장 다니면서 사이드 프로젝트 하시는 분', '퇴근 후 사이드 프로젝트 하시는 분들 어떤 거 하세요? 수익은 어느 정도 나나요?', '자유게시판', 118, NOW() - INTERVAL '5 days'),
(NULL, '서울 vs 지방 직장인 삶의 질', '서울에서 일하다가 지방으로 내려온 분들, 삶의 질이 어떻게 달라졌나요?', '자유게시판', 97, NOW() - INTERVAL '6 days'),
(NULL, '직장인 헬스 다니시는 분들', '출근 전 헬스 vs 퇴근 후 헬스 어느 게 지속 가능한가요? 루틴 공유해주세요.', '자유게시판', 83, NOW() - INTERVAL '7 days'),
(NULL, '오피스 필수 아이템 공유', '회사에 이거 없으면 안 된다! 싶은 사무용품이나 굿즈 추천해주세요.', '자유게시판', 56, NOW() - INTERVAL '8 days'),
(NULL, '직장인 취미 뭐 하세요?', '퇴근 후 스트레스 해소 겸 취미 생활 뭐 하시는지 궁금해요. 새 취미 찾고 있어요.', '자유게시판', 89, NOW() - INTERVAL '9 days'),
(NULL, '직장인 유튜브 채널 추천', '직장인에게 도움되는 유튜브 채널 추천해주세요. 재테크, 커리어, 자기계발 다 좋아요.', '자유게시판', 73, NOW() - INTERVAL '10 days'),
(NULL, '직장인 점심 도시락 싸다니는 분', '도시락 싸면 얼마나 절약되나요? 매일 싸는 게 힘들지 않나요? 팁 공유해주세요.', '자유게시판', 91, NOW() - INTERVAL '11 days'),
(NULL, '아이폰 vs 갤럭시 직장인 선택', '업무용으로 어느 폰이 더 유용한가요? 각자 장단점 얘기해봐요.', '자유게시판', 104, NOW() - INTERVAL '12 days'),
(NULL, '직장인 커피 하루 몇 잔 마시나요', '카페인 없인 못 사는 직장인인데 너무 많이 마시는 건지 걱정돼요. 다들 얼마나 마시세요?', '자유게시판', 67, NOW() - INTERVAL '13 days'),
(NULL, '출퇴근 거리 어느 정도면 괜찮나요', '편도 1시간 통근인데 너무 힘들어요. 이직할 때 거리 기준을 어떻게 잡으세요?', '자유게시판', 112, NOW() - INTERVAL '14 days'),
(NULL, '직장인 독서 어떻게 하세요', '책 읽고 싶은데 퇴근 후에 눈이 안 떠져요. 직장인 독서 습관 만드는 방법이 있나요?', '자유게시판', 78, NOW() - INTERVAL '15 days'),
(NULL, '직장인 결혼 준비 어떻게 하셨나요', '직장 다니면서 결혼 준비하는 게 너무 힘들어요. 어떻게 효율적으로 준비하셨나요?', '자유게시판', 96, NOW() - INTERVAL '16 days'),
(NULL, '혼자 사는 직장인 집밥 해먹나요', '퇴근하면 너무 지쳐서 배달시키는데 건강이 걱정돼요. 간단한 집밥 레시피 추천해주세요.', '자유게시판', 84, NOW() - INTERVAL '17 days'),
(NULL, '직장인 월 지출 얼마나 되세요', '연봉 4000대인데 월 지출이 250만원 정도예요. 많은 건가요 적은 건가요?', '자유게시판', 127, NOW() - INTERVAL '18 days'),
(NULL, '직장인 멘탈 관리 방법', '회사 스트레스로 주말에도 회사 생각이 나요. 완전히 끊어내는 방법이 있나요?', '자유게시판', 143, NOW() - INTERVAL '19 days'),
(NULL, '같은 회사 동기들이 다 떠나고 있어요', '입사 동기들이 하나둘 이직하는 걸 보면서 저도 나가야 하나 고민이 돼요.', '자유게시판', 108, NOW() - INTERVAL '20 days'),
(NULL, '직장인 어학 공부 어떻게 하세요', '영어 늘리고 싶은데 바빠서 시간이 없어요. 직장인 어학 공부 현실적인 방법 공유해주세요.', '자유게시판', 89, NOW() - INTERVAL '21 days'),
(NULL, '직장인 세컨드 브레인 뭐 쓰세요', 'Notion, Obsidian, Bear... 메모 툴 어떤 걸 쓰는 게 직장인한테 좋을까요?', '자유게시판', 73, NOW() - INTERVAL '22 days'),
(NULL, '직장인 투잡 현실', '월급 외 부수입 만드려고 투잡 생각 중인데 실제로 가능한가요? 경험자 조언 부탁드려요.', '자유게시판', 134, NOW() - INTERVAL '23 days'),
(NULL, '직장인 아파트 청약 전략', '무주택 직장인인데 청약 넣어야 하나요? 요즘 청약 시장 어떤가요?', '자유게시판', 118, NOW() - INTERVAL '24 days'),
(NULL, '회사 근처 방 구하는 거 추천하나요', '출퇴근 시간 줄이려고 회사 근처로 이사 고민 중이에요. 비용 대비 장점이 있을까요?', '자유게시판', 97, NOW() - INTERVAL '25 days'),
(NULL, '직장인 사진 취미 시작하고 싶어요', '카메라 입문하고 싶은데 직장인 취미로 적합한가요? 비용은 얼마나 드나요?', '자유게시판', 58, NOW() - INTERVAL '26 days'),
(NULL, '직장인 저축률 어느 정도가 적당한가요', '월급의 몇 % 저축이 현실적인가요? 서울 기준으로 생활비 빼면 얼마나 모을 수 있을까요?', '자유게시판', 143, NOW() - INTERVAL '27 days'),
(NULL, '직장인 주말이 너무 짧아요', '이틀이 너무 금방 지나가요. 주말을 효율적으로 쓰는 방법이 있나요?', '자유게시판', 112, NOW() - INTERVAL '28 days'),
(NULL, '회사 근처 점심 맛집 어떻게 찾나요', '회사 주변 맛집 찾는 앱이나 방법 공유해주세요. 항상 같은 곳만 가는 게 지겨워요.', '자유게시판', 64, NOW() - INTERVAL '29 days'),
(NULL, '직장인 자기 시간 확보 방법', '퇴근 후 나만의 시간 갖는 게 너무 힘들어요. 어떻게 해야 나를 위한 시간을 만들 수 있을까요?', '자유게시판', 134, NOW() - INTERVAL '30 days'),
(NULL, '직장인 노트북 추천', '재택근무용 노트북 뭐 쓰세요? 맥 vs 윈도우 어느 게 더 좋은지 의견 부탁드려요.', '자유게시판', 87, NOW() - INTERVAL '31 days'),
(NULL, '퇴근 후 자기계발 vs 쉬기', '퇴근 후 공부해야 성장한다는 말 vs 쉬어야 다음날 효율적이라는 말... 어느 쪽이 맞나요?', '자유게시판', 156, NOW() - INTERVAL '32 days'),
(NULL, '직장인 커리어 책 추천', '직장 생활과 커리어 성장에 도움이 된 책 추천해주세요.', '자유게시판', 91, NOW() - INTERVAL '33 days'),
(NULL, '직장인 탈모 진짜 심해지나요', '스트레스로 탈모가 왔는데 직장인 탈모 관리 어떻게 하세요?', '자유게시판', 108, NOW() - INTERVAL '34 days'),
(NULL, '직장인 꿈이 없어졌어요', '취업 전엔 꿈이 있었는데 직장 다니면서 그냥 월급 받으러 가는 느낌이에요. 다들 이런가요?', '자유게시판', 178, NOW() - INTERVAL '35 days'),
(NULL, '직장인 반려동물 키우기', '혼자 사는 직장인인데 반려동물 키우고 싶어요. 현실적으로 가능한가요?', '자유게시판', 94, NOW() - INTERVAL '36 days'),
(NULL, '직장인 재테크 실패담', '주식으로 1000만원 날린 경험 공유합니다. 다들 실패 경험 있으신가요?', '자유게시판', 127, NOW() - INTERVAL '37 days'),
(NULL, '직장인 건강검진 어디서 받으세요', '회사 건강검진 말고 추가로 받는 분들 있나요? 어디서 어떻게 받는 게 좋은가요?', '자유게시판', 76, NOW() - INTERVAL '38 days'),
(NULL, '30대 직장인 인간관계 어떻게 관리하세요', '30대 되니까 관계 정리가 필요한 것 같아요. 어떻게 관리하시나요?', '자유게시판', 112, NOW() - INTERVAL '39 days'),
(NULL, '직장 그만두고 싶을 때 버티는 법', '오늘도 그만두고 싶었는데 어떻게 마음 다잡으세요? 다들 어떻게 버티나요?', '자유게시판', 187, NOW() - INTERVAL '40 days'),
(NULL, '직장인 점심 혼자 먹기 VS 같이 먹기', '혼자 먹는 게 편한 내향인인데 팀 문화가 다 같이 먹는 분위기예요. 어떻게 하세요?', '자유게시판', 89, NOW() - INTERVAL '41 days'),
(NULL, '직장인 내 집 마련 현실', '서울에서 월급 모아 내 집 마련이 가능한가요? 아니면 지방으로 가야 하나요?', '자유게시판', 164, NOW() - INTERVAL '42 days'),
(NULL, '직장인 AI 업무 활용 어디까지 하세요', 'ChatGPT, Claude로 업무 효율 높이는 분들 어떻게 활용하시나요?', '자유게시판', 143, NOW() - INTERVAL '43 days'),
(NULL, '직장인 친목 동호회 어때요', '회사 동호회 들어가볼까 고민 중인데 괜찮은가요? 아니면 회사 사람과 엮이면 복잡해지나요?', '자유게시판', 74, NOW() - INTERVAL '44 days'),
(NULL, '직장인 영어 공부 방법 추천', '영어 면접 준비 및 업무 활용을 위한 영어 공부 효율적인 방법 알려주세요.', '자유게시판', 97, NOW() - INTERVAL '45 days'),
(NULL, '직장 생활 하면서 가장 행복했던 순간', '직장 생활이 힘들 때 이 글 보고 위로받으세요. 저는 첫 연봉 통장에 찍혔을 때가 제일 뿌듯했어요.', '자유게시판', 134, NOW() - INTERVAL '46 days'),
(NULL, '직장인 운동 루틴 공유해주세요', '퇴근 후 지쳐도 운동을 꾸준히 하시는 분들 어떻게 동기부여 하세요?', '자유게시판', 108, NOW() - INTERVAL '47 days'),
(NULL, '직장인 SNS 어떻게 관리하세요', '직장 동료한테 SNS 팔로우 요청 어떻게 해야 할까요? 거절하기도 그렇고 수락하기도 그렇고.', '자유게시판', 83, NOW() - INTERVAL '48 days'),
(NULL, '이 직장 이것만 좋아요', '불만은 많지만 딱 하나, 이것 때문에 다니고 있어요. 여러분의 버티는 이유는 뭔가요?', '자유게시판', 198, NOW() - INTERVAL '49 days');
